class Ticket(val no: Int) {
    companion object {
        var made = 0

        fun next(): Ticket {
            made = made + 1
            return Ticket(made)
        }
    }
}

fun main() {
    val a = Ticket.next()
    val b = Ticket.next()
    println(a.no)
    println(b.no)
    println(Ticket.made)
}

